mapper.select:
select R.ORDER_NO as orderNo, R.REFUND_ORDER_NO as refundOrderNo, R.PLATFORM_REFUND_NO as platformRefundNo, R.REFUND_AMOUNT as refundAmount, R.REFUND_STATUS as refundStatus, R.REFUND_TYPE as refundType, R.REFUND_DATE as refundDate, R.VERIFY_AFTER_TIME as verifyAfterTime, R.CREATE_TIME as createTime, R.UPDATE_TIME as updateTime, O.PAYMENT_ORDER_NO as paymentOrderNo, O.TICKET_NAME as ticketName, O.ORDER_STATUS as orderStatus, I.TICKET_STATUS as ticketStatus from DAILY_TICKET_REFUND R left join DAILY_TICKET_ORDER O on O.ORDER_NO = R.ORDER_NO left join DAILY_TICKET_INSTANCE I on I.ORDER_NO = R.ORDER_NO
and R.CREATE_TIME >= #{beginTime,jdbcType=TIMESTAMP}
and R.CREATE_TIME <= #{endTime,jdbcType=TIMESTAMP}
and R.ORDER_NO = #{orderNo,jdbcType=VARCHAR}
and O.PAYMENT_ORDER_NO = #{paymentOrderNo,jdbcType=VARCHAR}
and R.REFUND_ORDER_NO = #{refundOrderNo,jdbcType=VARCHAR}
and R.REFUND_STATUS = #{refundStatus,jdbcType=VARCHAR}
order by R.CREATE_TIME desc

