mapper.update:
update DAILY_TICKET_REFUND
set REFUND_STATUS = #{refundStatus,jdbcType=VARCHAR},
    PLATFORM_REFUND_NO = NVL(#{platformRefundNo,jdbcType=VARCHAR}, PLATFORM_REFUND_NO),
    REFUND_DATE = #{refundDate,jdbcType=TIMESTAMP},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where ORDER_NO = #{orderNo,jdbcType=VARCHAR}
